/* prog27_soundex – reproduced from the obfuscated binary.
 *
 * Behaviour:
 *   * If no argument is supplied, or the supplied string is empty,
 *     the program prints the line "EMPTY".
 *   * Otherwise it prints the 4‑character Soundex code of the first
 *     argument, exactly as the original binary does.
 *
 * The Soundex algorithm implemented matches the classic US Census
 * version:
 *   – Keep the first letter (converted to upper case).
 *   – Encode the remaining letters using the mapping
 *       B,F,P,V → 1
 *       C,G,J,K,Q,S,X,Z → 2
 *       D,T → 3
 *       L → 4
 *       M,N → 5
 *       R → 6
 *     (all other characters → 0).
 *   – Consecutive identical codes are collapsed, and zeros are
 *     ignored (they do not terminate the code).
 *   – The code is padded with '0' characters to a total length of
 *     four characters (first letter + three digits).
 *
 * The implementation below follows the same logic that the
 * de‑compiled control‑flow of the binary expresses, but in clear,
 * idiomatic C.
 */

#include <stdio.h>
#include <string.h>

/* Return the Soundex digit for an upper‑case letter.
 * 0 is returned for characters that do not map to a digit. */
static unsigned int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T':                     return 3;
        case 'L':                               return 4;
        case 'M': case 'N':                     return 5;
        case 'R':                               return 6;
        default:                                return 0;
    }
}

/* Convert a character to upper case if it is a lower‑case ASCII letter.
 * The original binary performed the conversion manually (by
 * subtracting 0x20) only for the range 'a'‑'z'. */
static char to_upper_ascii(char c)
{
    if ('a' <= c && c <= 'z')
        return (char)(c - ('a' - 'A'));
    return c;
}

int main(int argc, char *argv[])
{
    /* No argument → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* Empty string → print EMPTY */
    if (len == 0) {
        puts("EMPTY");
        return 0;
    }

    /* Buffer for the final 4‑character code plus null terminator */
    char code[5];
    /* First character: upper‑cased version of the first input character */
    code[0] = to_upper_ascii(input[0]);

    /* Compute the digit for the first character (used to suppress
       a duplicate digit at the start of the rest of the string). */
    unsigned int prev_digit = soundex_digit(code[0]);

    int out_len = 1;  /* we already have the first letter */

    /* Process the rest of the input string */
    for (size_t i = 1; i < len && out_len < 4; ++i) {
        char ch = to_upper_ascii(input[i]);
        unsigned int digit = soundex_digit(ch);

        if (digit == 0)
            continue;               // skip vowels, H, W, Y, etc.
        if (digit == prev_digit)
            continue;               // collapse consecutive duplicates

        code[out_len++] = (char)('0' + digit);
        prev_digit = digit;
    }

    /* Pad with '0' if we have fewer than 4 characters */
    while (out_len < 4) {
        code[out_len++] = '0';
    }

    code[4] = '\0';   // null‑terminate
    puts(code);
    return 0;
}
